xpath.script:
document.addEventListener('DOMContentLoaded', function() {
    const form = document.getElementById('product_request_form');
    if (!form) return;

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const submitBtn = form.querySelector('button[type="submit"]');
        const successMsg = document.getElementById('request_success');
        const errorMsg = document.getElementById('request_error');
        const errorText = document.getElementById('error_message');

        // Hide previous messages
        successMsg.classList.add('d-none');
        errorMsg.classList.add('d-none');

        // Disable button
        submitBtn.disabled = true;
        submitBtn.innerHTML = ' Sending...';

        // Get form data
        const formData = new FormData(form);
        const data = {
            product_id: formData.get('product_id'),
            email: formData.get('email'),
            message: formData.get('message') || ''
        };

        // Send request
        fetch('/shop/product/request_availability', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: data
            })
        })
        .then(response => response.json())
        .then(result => {
            if (result.result && result.result.success) {
                successMsg.classList.remove('d-none');
                form.reset();
            } else {
                errorText.textContent = result.result?.error || 'Error sending request.';
                errorMsg.classList.remove('d-none');
            }
        })
        .catch(error => {
            console.error('Error:', error);
            errorText.textContent = 'Network error. Please try again.';
            errorMsg.classList.remove('d-none');
        })
        .finally(() => {
            submitBtn.disabled = false;
            submitBtn.innerHTML = ' Send Request';
        });
    });
});
